    F32(f32),
    /// A raw u32 property (color `0xAARRGGBB`, an `EVENT_LISTENERS` mask, …).
    U32(u32),
    /// A boolean property (visible, clips_to_bounds, …).
    Bool(bool),
    /// An enum property wire value (alignment, text alignment, truncation, …).
    Enum(u8),
    /// A string (text content, font family).
    Str(String),
}

