 fn emit_frame(engine: &mut Engine, root: &Node) -> Vec<u8> {
     let (mut mem, layout) = with_memory();
     {
         let mut guest = Guest::new(&mut mem, &layout);
         guest.begin_frame();
         engine.emit(root, &mut guest).expect("emit");
         guest.end_frame();
     }
     read_frame(&mut mem, &layout)
