 /// The diff-based reactive emitter.
 ///
 /// `Engine` keeps the snapshot of what was last emitted and owns the signal
 /// store. Calling `emit` with a (possibly mutated) retained tree writes only
 /// the delta opcodes; `set_signal` writes deltas for only the bound nodes.
 pub struct Engine {
     /// nodeId to last emitted state (a preallocated slab; node ids are dense).
     snapshot: Vec<Option<SnapshotNode>>,
     /// Monotonic generation stamp for the current pass.
     gen: u64,
     /// Reactive signal runtime (values + computed/effects + node dependencies).
     store: Runtime,
     /// Window/surface metadata signal bindings (`META::SET_WINDOW_METADATA`).
     window: WindowMetadata,
     /// The last window metadata written to the wire (dedupe / clear detection).
     window_emitted: WindowMeta,
 }

 impl Default for Engine {
     fn default() -> Self {
         Self::new()
     }
 }

 impl Engine {
     pub fn new() -> Self {
         Self {
             snapshot: Vec::new(),
             gen: 0,
             store: Runtime::new(),
             window: WindowMetadata::new(),
             window_emitted: WindowMeta::new(),
         }
     }

     /// The shared reactive runtime (for creating typed signals / computeds).
     pub fn runtime(&self) -> Runtime {
         self.store.clone()
     }

     /// Reconcile `root` against the snapshot, emitting only changed opcodes.
     pub fn emit(
         &mut self,
         root: &Node,
         guest: &mut Guest<'_>,
     ) -> Result<EmitResult, pathland_core::RingError> {
         self.gen = self.gen.wrapping_add(1);
         // Rebuild the signal->node dependency index from scratch; reconcile
         // re-adds the bindings this tree actually uses, so stale subscriptions
         // vanish.
         self.store.clear_node_deps();
         // Window metadata is renderer-global, not part of the tree: emit the
         // initial values (and any rebind/clear) before the node opcodes.
         let mut out = self.emit_window_metadata(guest)?;
         self.reconcile_node(root, None, 0, guest, &mut out)?;

         for (id, slot) in self.snapshot.iter_mut().enumerate() {
             if let Some(s) = slot {
                 if s.gen != self.gen {
                     if let Some(parent) = s.parent {
                         guest.remove_child(parent, id as u32)?;
                         out += 1;
                     }
                     guest.delete_node(id as u32)?;
                     out += 1;
                     *slot = None;
                 }
             }
         }
         Ok(EmitResult { opcodes: out })
     }

     /// Number of nodes tracked in the snapshot (diagnostics).
     pub fn tracked_nodes(&self) -> usize {
         self.snapshot.iter().filter(|s| s.is_some()).count()
     }

