 fn with_guest() -> (Vec<u8>, MemoryLayout) {
     let layout = MemoryLayout::default();
     let mut mem = vec![0u8; layout.total_bytes()];
     init_memory(&mut mem, &layout);
     (mem, layout)
 }

 fn text_node(text: &str) -> Node {
     Node {
         id: 0,
         component: Component::Text { text: text.into() },
         children: Vec::new(),
