 fn ops_after_set(
     engine: &mut Engine,
     signal: pathland_engine::SignalId,
     value: SignalValue,
     mem: &mut [u8],
     layout: &MemoryLayout,
     root: &Node,
 ) -> (usize, Vec<(u32, String)>) {
