     /// The Rust view DSL's media kit, end to end into the renderer's tree
     /// (spec/MEDIA.md): a `MediaController` + `attach()` + a `Video` surface emit
     /// a non-visual `MEDIA_CONTROLLER` node carrying its transport, and the
     /// surface is linked to it by `MEDIA_CONTROLLER_ID`.
     #[test]
     fn media_surface_from_the_view_dsl_reaches_the_render_tree() {
         let layout = MemoryLayout::default();
         let mut mem = vec![0u8; layout.total_bytes()];
         init_memory(&mut mem, &layout);

         let mut engine = Engine::new();
         let player = Rc::new(MediaController::with_source(
             &engine.runtime(),
             "/assets/clip.mp4",
         ));
         player.play();

         let mut root = vstack![player.attach(), Video::new(player.clone())].build();
         assign_ids(&mut root, &mut 1);
         {
             let mut guest = Guest::new(&mut mem, &layout);
             guest.begin_frame();
             engine.emit(&root, &mut guest).unwrap();
             guest.end_frame();
         }

         let mut host = pathland_core::Host::new(&mut mem, &layout);
         let tree = render_tree_from_frame(&host.frames()[0]);

         let controller = tree
             .nodes
             .values()
             .find(|n| n.component_type == component_type::MEDIA_CONTROLLER)
             .expect("the controller's non-visual node");
         // The controller carries the resource and the transport (the app drives
         // playback through them).
         assert_eq!(
             controller.string_property(pathland_core::property_id::MEDIA_SOURCE),
             Some("/assets/clip.mp4")
         );
         assert_eq!(
             controller.u32_property(pathland_core::property_id::PLAYBACK_STATE, 0),
             1,
             "playing was set before the emit"
         );

         let surface = tree
             .nodes
             .values()
             .find(|n| n.component_type == component_type::VIDEO)
             .expect("the video surface");
         assert_eq!(
             surface.u32_property(pathland_core::property_id::MEDIA_CONTROLLER_ID, 0),
             controller.id,
             "the surface points at the controller's node"
         );
     }

     /// `LIST` (`FIT_QUERY`) and `SET_DATE` decode into the shared tree, so the
     /// Qt renderer can measure a fit slot and format a date (spec/PRIMITIVES.md).
     #[test]
     fn decodes_list_and_date_values() {
         // The ring arena entry is `[u32 byteLen][payload]` (Guest::alloc); a
         // LIST payload is `[u32 count][f32 × count]` (spec/OPCODE.md).
         let mut payload = Vec::new();
         payload.extend_from_slice(&2u32.to_le_bytes());
         payload.extend_from_slice(&320.0f32.to_bits().to_le_bytes());
         payload.extend_from_slice(&640.0f32.to_bits().to_le_bytes());
         let mut arena = Vec::new();
         arena.extend_from_slice(&(payload.len() as u32).to_le_bytes());
         arena.extend_from_slice(&payload);

         let ops = [
             Opcode::new(
                 category::TREE,
                 tree::CREATE_NODE,
                 0,
                 1,
                 component_type::SIZE_THAT_FITS as u32,
                 0,
             ),
             Opcode::new(
                 category::PARAMETER,
                 parameter::SET_PROPERTY,
                 0,
                 1,
                 ((value_type::LIST as u32) << 16)
                     | pathland_core::property_id::FIT_QUERY as u32,
                 0,
             ),
             Opcode::new(category::PARAMETER, parameter::SET_DATE, 0, 1, 19_723, 3_600_000),
         ];
         let slots: Vec<u8> = ops.iter().flat_map(|o| o.to_bytes()).collect();
         let frame = Frame::from_parts(&slots, &arena, 0, slots.len());
         let tree = render_tree_from_frame(&frame);

         let node = tree.node(1).unwrap();
         assert_eq!(
             node.list_property(pathland_core::property_id::FIT_QUERY),
             Some([320.0f32, 640.0].as_slice())
         );
         assert_eq!(node.date, Some((19_723, 3_600_000)));
     }

