         tree.nodes.insert(2, node(component_type::TEXT, &[(property_id::HEIGHT, f32_bits(-1.0))]));
         assert_eq!(
             main_axis_align(&stack, v, &tree),
             Align::Fill,
             "a FILL child propagates main-axis fill"
