         let c = *color;
         let red = (((c >> 16) & 0xFF) as u16) * 257;
         let green = (((c >> 8) & 0xFF) as u16) * 257;
         let blue = ((c & 0xFF) as u16) * 257;
         let mut fg = pango::AttrColor::new_foreground(red, green, blue);
         fg.set_start_index(0);
         fg.set_end_index(u32::MAX);
         attrs.insert(fg);
