//! Shared inline Markdown parser for Pathland.
//!
//! Parses a small inline subset into a
//! [`pathland_core::AttributedString`]:
//!
//! - `**bold**` → `FONT_WEIGHT` 700
//! - `*italic*` → `FONT_STYLE` Italic
//! - `` `code` `` → `FONT_DESIGN` Monospaced
//! - `~~strikethrough~~` → `STRIKETHROUGH` 1
//! - `[label](url)` → link run (label text is parsed recursively)
//! - `\` escapes the next character
//!
//! The parser is `no_std` + `alloc` and is shared by every DSL: the Rust DSL
//! calls [`parse`] directly; foreign hosts (Java/JNA) call the C ABI in
//! [`capi`]. Block-level Markdown, images, and reference links are out of
//! scope for v1.

#![no_std]

extern crate alloc;

#[cfg(test)]
extern crate std;

pub mod capi;

use alloc::string::String;
use alloc::vec::Vec;
use pathland_core::{AttributedString, LinkRun, StyleRun};

/// Parse inline Markdown into an [`AttributedString`].
///
/// Returns `None` only if the produced ranges fail the model's validation
/// (which should not happen for well-formed UTF-8 input; the parser never
/// splits code points).
#[must_use]
pub fn parse(input: &str) -> Option<AttributedString> {
    let mut text = String::new();
    let mut runs = Vec::new();
    let mut links = Vec::new();
    parse_into(input, &mut text, &mut runs, &mut links);
    AttributedString::new(text, runs, links).ok()
}

fn parse_into(input: &str, text: &mut String, runs: &mut Vec<StyleRun>, links: &mut Vec<LinkRun>) {
    let bytes = input.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'\\' => {
                let next = next_char(input, i + 1);
                match next {
                    Some((ch, end)) => {
                        text.push(ch);
                        i = end;
                    }
                    None => {
                        text.push('\\');
                        i += 1;
                    }
                }
            }
            b'*' if bytes.get(i + 1) == Some(&b'*') => {
                if let Some(end) = find_delimiter(input, i + 2, "**") {
                    let start = text.len();
                    parse_into(&input[i + 2..end], text, runs, links);
                    runs.push(StyleRun::new(byte_len(start), byte_len(text.len())).bold());
                    i = end + 2;
                } else {
                    text.push('*');
                    i += 1;
                }
            }
            b'*' => {
                if let Some(end) = find_delimiter(input, i + 1, "*") {
                    let start = text.len();
                    parse_into(&input[i + 1..end], text, runs, links);
                    runs.push(StyleRun::new(byte_len(start), byte_len(text.len())).italic());
                    i = end + 1;
                } else {
                    text.push('*');
                    i += 1;
                }
            }
            b'~' if bytes.get(i + 1) == Some(&b'~') => {
                if let Some(end) = find_delimiter(input, i + 2, "~~") {
                    let start = text.len();
                    parse_into(&input[i + 2..end], text, runs, links);
                    runs.push(
                        StyleRun::new(byte_len(start), byte_len(text.len())).strikethrough(),
                    );
                    i = end + 2;
                } else {
                    text.push('~');
                    i += 1;
                }
            }
            b'`' => {
                if let Some(end) = find_delimiter(input, i + 1, "`") {
                    let start = text.len();
                    text.push_str(&input[i + 1..end]);
                    runs.push(StyleRun::new(byte_len(start), byte_len(text.len())).monospaced());
                    i = end + 1;
                } else {
                    text.push('`');
                    i += 1;
                }
            }
            b'[' => {
                if let Some((label_end, url, after)) = parse_link(input, i) {
                    let start = text.len();
                    parse_into(&input[i + 1..label_end], text, runs, links);
                    links.push(LinkRun::new(byte_len(start), byte_len(text.len()), url));
                    i = after;
                } else {
                    text.push('[');
                    i += 1;
                }
            }
            _ => {
                let (ch, end) = next_char(input, i).expect("valid utf-8 boundary");
                text.push(ch);
                i = end;
            }
        }
    }
}

fn byte_len(value: usize) -> u32 {
    u32::try_from(value).unwrap_or(u32::MAX)
}

/// Find the next occurrence of `needle` at or after `from`, returning its byte
/// offset. Escaped characters are skipped.
fn find_delimiter(input: &str, from: usize, needle: &str) -> Option<usize> {
    let bytes = input.as_bytes();
    let mut i = from;
    while i < bytes.len() {
        if bytes[i] == b'\\' {
            i += 2;
            continue;
        }
        if input[i..].starts_with(needle) {
            return Some(i);
        }
        i = next_char(input, i)?.1;
    }
    None
}

/// Parse `[label](url)` at `open`. Returns `(label_end, url, after_close)`.
fn parse_link(input: &str, open: usize) -> Option<(usize, &str, usize)> {
    let bytes = input.as_bytes();
    let mut i = open + 1;
    while i < bytes.len() {
        if bytes[i] == b'\\' {
            i += 2;
            continue;
        }
        if bytes[i] == b']' && bytes.get(i + 1) == Some(&b'(') {
            let label_end = i;
            let url_start = i + 2;
            let mut j = url_start;
            while j < bytes.len() {
                if bytes[j] == b'\\' {
                    j += 2;
                    continue;
                }
                if bytes[j] == b')' {
                    return Some((label_end, &input[url_start..j], j + 1));
                }
                j = next_char(input, j)?.1;
            }
            return None;
        }
        i = next_char(input, i)?.1;
    }
    None
}

fn next_char(input: &str, at: usize) -> Option<(char, usize)> {
    let ch = input[at..].chars().next()?;
    Some((ch, at + ch.len_utf8()))
}

#[cfg(test)]
mod tests {
    use super::*;
    use pathland_core::{property_id, value_type};

    fn decoded(markdown: &str) -> AttributedString {
        parse(markdown).expect("parser output is valid")
    }

    #[test]
    fn plain_text_has_no_runs() {
        let value = decoded("hello");
        assert_eq!(value.text(), "hello");
        assert!(value.runs().is_empty());
        assert!(value.links().is_empty());
    }

    #[test]
    fn maps_each_inline_marker() {
        let value = decoded("**b** *i* `c` ~~s~~");
        assert_eq!(value.text(), "b i c s");
        assert_eq!(value.runs().len(), 4);
        assert_eq!(value.runs()[0].start, 0);
        assert_eq!(value.runs()[0].end, 1);
        assert!(value.runs()[0].attributes.iter().any(|a| {
            a.property == property_id::FONT_WEIGHT && a.value == 700.0f32.to_bits()
        }));
        assert!(value.runs()[1].attributes.iter().any(|a| {
            a.property == property_id::FONT_STYLE && a.value == 1.0f32.to_bits()
        }));
        assert!(value.runs()[2].attributes.iter().any(|a| {
            a.property == property_id::FONT_DESIGN && a.value == 3.0f32.to_bits()
        }));
        assert!(value.runs()[3].attributes.iter().any(|a| {
            a.property == property_id::STRIKETHROUGH && a.value_type == value_type::U8
        }));
    }

    #[test]
    fn nests_formats() {
        let value = decoded("**bold *and italic***");
        assert_eq!(value.text(), "bold and italic");
        assert_eq!(value.runs().len(), 2);
        assert_eq!(value.runs()[0].start, 5);
        assert_eq!(value.runs()[0].end, 16);
        assert_eq!(value.runs()[1].start, 0);
        assert_eq!(value.runs()[1].end, 16);
    }

    #[test]
    fn links_carry_label_runs_and_url() {
        let value = decoded("[**hi**](https://example.com)");
        assert_eq!(value.text(), "hi");
        assert_eq!(value.links().len(), 1);
        assert_eq!(value.links()[0].url, "https://example.com");
        assert_eq!(value.links()[0].start, 0);
        assert_eq!(value.links()[0].end, 2);
        assert_eq!(value.runs().len(), 1);
    }

    #[test]
    fn code_spans_do_not_parse_inner_markup() {
        let value = decoded("`**not bold**`");
        assert_eq!(value.text(), "**not bold**");
        assert_eq!(value.runs().len(), 1);
        assert_eq!(value.runs()[0].attributes[0].property, property_id::FONT_DESIGN);
    }

    #[test]
    fn escapes_are_literal() {
        let value = decoded(r"\*not italic\*");
        assert_eq!(value.text(), "*not italic*");
        assert!(value.runs().is_empty());
    }

    #[test]
    fn unmatched_markers_stay_literal() {
        let value = decoded("a * b ** c");
        assert_eq!(value.text(), "a * b ** c");
        assert!(value.runs().is_empty());
    }

    #[test]
    fn utf8_offsets_are_bytes() {
        let value = decoded("é**ü**");
        assert_eq!(value.text(), "éü");
        assert_eq!(value.runs()[0].start, 2);
        assert_eq!(value.runs()[0].end, 4);
    }

    #[test]
    fn c_abi_round_trips() {
        let input = "**hi** [x](y)";
        let mut len = 0u32;
        let ptr = capi::pathland_markdown_parse(input.as_ptr(), input.len(), &mut len);
        assert!(!ptr.is_null());
        let bytes = unsafe { core::slice::from_raw_parts(ptr, len as usize) };
        let value = AttributedString::decode(bytes).unwrap();
        assert_eq!(value.text(), "hi x");
        assert_eq!(value.links().len(), 1);
        capi::pathland_markdown_free(ptr, len);
    }

    #[test]
    fn c_abi_rejects_invalid_utf8() {
        let bytes = [0xFFu8, 0xFE];
        let mut len = 0u32;
        let ptr = capi::pathland_markdown_parse(bytes.as_ptr(), bytes.len(), &mut len);
        assert!(ptr.is_null());
    }
}

//! C ABI for foreign hosts (Java/JNA, Swift, …).
//!
//! `pathland_markdown_parse` returns an owned buffer containing the encoded
//! `AttributedString` arena payload (the bytes the caller allocates into an
//! arena/string section). The caller must release it with
//! `pathland_markdown_free(ptr, len)`.

use alloc::alloc::{alloc, dealloc, Layout};
use core::ptr;

/// Parse inline Markdown and return an owned payload buffer.
///
/// # Safety
///
/// `input` must point to `input_len` readable bytes (or be null when
/// `input_len == 0`). `out_len` must be a valid, writable `u32` pointer.
/// Returns null on invalid UTF-8 or an encoding failure; `out_len` is set to 0.
#[no_mangle]
pub unsafe extern "C" fn pathland_markdown_parse(
    input: *const u8,
    input_len: usize,
    out_len: *mut u32,
) -> *mut u8 {
    if out_len.is_null() {
        return ptr::null_mut();
    }
    unsafe { *out_len = 0 };
    if input.is_null() && input_len != 0 {
        return ptr::null_mut();
    }

    let bytes = if input_len == 0 {
        &[][..]
    } else {
        unsafe { core::slice::from_raw_parts(input, input_len) }
    };
    let Ok(text) = core::str::from_utf8(bytes) else {
        return ptr::null_mut();
    };
    let Some(value) = crate::parse(text) else {
        return ptr::null_mut();
    };
    let Ok(payload) = value.encode() else {
        return ptr::null_mut();
    };
    if payload.is_empty() {
        return ptr::null_mut();
    }

    let Ok(layout) = Layout::array::<u8>(payload.len()) else {
        return ptr::null_mut();
    };
    let buffer = unsafe { alloc(layout) };
    if buffer.is_null() {
        return ptr::null_mut();
    }
    unsafe {
        ptr::copy_nonoverlapping(payload.as_ptr(), buffer, payload.len());
        *out_len = payload.len() as u32;
    }
    buffer
}

/// Release a buffer returned by [`pathland_markdown_parse`].
///
/// # Safety
///
/// `ptr`/`len` must come from one successful `pathland_markdown_parse` call.
#[no_mangle]
pub unsafe extern "C" fn pathland_markdown_free(ptr: *mut u8, len: u32) {
    if ptr.is_null() || len == 0 {
        return;
    }
    if let Ok(layout) = Layout::array::<u8>(len as usize) {
        unsafe { dealloc(ptr, layout) };
    }
}

