#[cfg(test)]
mod tests {
    use super::*;
    use pathland_core::AttributedString;

    #[test]
    fn round_trips() {
        let input = "**hi** [x](y)";
        let mut len = 0u32;
        let ptr = unsafe { pathland_markdown_parse(input.as_ptr(), input.len(), &mut len) };
