    guest.end_frame();
    let mut host = Host::new(mem, layout);
    let frames = host.frames();
    let ops = frames
        .first()
        .map(|f| f.opcodes().collect::<Vec<Opcode>>())
        .unwrap_or_default();
    (n, ops)
}

