+            if (!dir.mkdirs()) {
+                return null;
+            }
+            File out = new File(dir, fileName);
+            try (var copy = new FileOutputStream(out)) {
+                stream.transferTo(copy);
+            }
+            out.setExecutable(true, false);
+            return out.getAbsolutePath();
+        } catch (IOException e) {
+            return null;
+        }
+    }
