         self.snapshot
             .get_mut(node as usize)
             .and_then(|s| s.as_mut())
     }

     fn snapshot_text(&self, node: u32) -> Option<&str> {
         self.snapshot
             .get(node as usize)
             .and_then(|s| s.as_ref())
             .and_then(|s| s.text.as_deref())
     }

     fn snapshot_property(&self, node: u32, prop: u16) -> Option<u32> {
         self.snapshot
             .get(node as usize)
             .and_then(|s| s.as_ref())
             .and_then(|s| s.properties.get(&prop).copied())
     }

     fn snapshot_string(&self, node: u32, prop: u16) -> Option<&str> {
         self.snapshot
             .get(node as usize)
             .and_then(|s| s.as_ref())
             .and_then(|s| s.string_properties.get(&prop))
             .map(|(value, _)| value.as_str())
     }

